using System;using System.IO;using System.Net;using System.Reflection;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Collections.Generic;using System.Windows.Forms;using Microsoft.Web.WebView2.Core;
namespace IrisDesktop {
 public static class Online043Entry {
  static string owner,root;static int failure=1;static readonly JavaScriptSerializer json=new JavaScriptSerializer();
  static string Read(string path,string method="GET"){var r=(HttpWebRequest)WebRequest.Create("http://localhost:3000"+path);r.Proxy=null;r.AllowAutoRedirect=false;r.Method=method;r.Timeout=5000;r.Headers["X-Astra-Validation-Owner"]=owner;using(var response=r.GetResponse())using(var reader=new StreamReader(response.GetResponseStream()))return reader.ReadToEnd();}
  static Dictionary<string,object> State(){return json.DeserializeObject(Read("/__fixture/state")) as Dictionary<string,object>;}
  static void Require(bool ok,string text){if(!ok)throw new InvalidOperationException(text);}
  static void Stage(string value){File.AppendAllText(Path.Combine(root,"stages.txt"),DateTime.UtcNow.ToString("o")+" "+value+Environment.NewLine);Console.WriteLine(value);}
  static object Field(object target,string name){return target.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(target);}
  static async Task Tick(DesktopWebView form,bool force=false){var c=(DesktopOnlineConnection)Field(form,"online");if(force)typeof(DesktopOnlineConnection).GetField("next",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(c,DateTime.MinValue);await c.TickAsync();}
  static object Invoke(DesktopWebView form,string method,params object[] args){return typeof(DesktopWebView).GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,args);}
  static async Task<bool> Probe(DesktopWebView form,string expression){return await form.Browser.CoreWebView2.ExecuteScriptAsync("(()=>{"+expression+"})()") == "true";}
  static async Task Wait(DesktopWebView form,string expression,string label){for(int i=0;i<100;i++){if(await Probe(form,expression))return;await Task.Delay(100);}var body=await form.Browser.CoreWebView2.ExecuteScriptAsync("JSON.stringify({body:document.body.innerText,errors:window.fixtureErrors})");throw new InvalidOperationException(label+": "+body);}
  static async Task Click(DesktopWebView form,string selector){await Wait(form,"const b=document.querySelector("+json.Serialize(selector)+");return !!b&&!b.disabled;","enabled button "+selector);await form.Browser.CoreWebView2.ExecuteScriptAsync("document.querySelector("+json.Serialize(selector)+").click()");await Task.Delay(150);}
  static async Task TextClick(DesktopWebView form,string text){string expr="const b=[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==="+json.Serialize(text)+"&&!b.disabled);";await Wait(form,expr+"return !!b;","button "+text);await form.Browser.CoreWebView2.ExecuteScriptAsync("(()=>{"+expr+"b.click();})()");await Task.Delay(150);}
  static async Task Login(DesktopWebView form,string name){await Wait(form,"return !!document.querySelector('form input[autocomplete=username]');","login UI");await form.Browser.CoreWebView2.ExecuteScriptAsync("(()=>{const f=[...document.querySelectorAll('form')].find(f=>f.querySelector('[autocomplete=username]'));const inputs=[f.querySelector('[autocomplete=username]'),f.querySelector('[autocomplete=current-password]')];const setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;inputs.forEach((e,i)=>{setter.call(e,i===0?"+json.Serialize(name)+":'synthetic-only');e.dispatchEvent(new Event('input',{bubbles:true}));});})()");await Task.Delay(100);await form.Browser.CoreWebView2.ExecuteScriptAsync("document.querySelector('form').requestSubmit()");await Wait(form,"return !!document.querySelector('[aria-label=\"생텀 계정 연결됨\"]')&&!document.querySelector('form input[autocomplete=username]');","authenticated full workspace "+name);}
  static async Task Select(DesktopWebView form,string name){await Click(form,"[aria-label='캐릭터 선택']");await Click(form,"[aria-label='"+name+"캐릭터 전사']");await Wait(form,"return document.body.innerText.includes("+json.Serialize(name+"캐릭터")+");","selected character");}
  static void Account(string expected){var a=(object[])State()["accounts"];Require(a.Length==(expected==null?0:1),"online count");if(expected!=null)Require(Equals(((Dictionary<string,object>)a[0])["accountId"],expected),"account ownership");}
  static async Task Capture(DesktopWebView form,string name){using(var stream=File.Create(Path.Combine(root,name+".png")))await form.Browser.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,stream);}
  [STAThread]public static int Main(string[] args){
   Console.OutputEncoding=System.Text.Encoding.UTF8;
   if(args.Length!=4||args[0]!="--test-root"||args[2]!="--owned-gui"||(args[3]!="--full-ui"&&args[3]!="--connection-probe")){Console.WriteLine("NOT_RUN: explicit owned 043 fixture required");return 2;}
   try{root=Path.GetFullPath(args[1]);string allowed=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"profiles")+Path.DirectorySeparatorChar;Require(root.StartsWith(allowed,StringComparison.OrdinalIgnoreCase),"dedicated profile");owner=File.ReadAllText(Path.Combine(root,"fixture-owner.txt")).Trim();Guid parsed;Require(Guid.TryParse(owner,out parsed)&&!DesktopBridge.ErgonAvailable,"owner/ERGON lock");Require(Read("/__astra_validation")==owner,"owned API");Require(Equals(State()["database"],"synthetic-lease-model"),"explicit synthetic model required");}catch(Exception error){Console.WriteLine("NOT_RUN: owned fixture preflight failed: "+error);return 2;}
   Application.EnableVisualStyles();using(var form=new DesktopWebView(true,Path.Combine(root,"WebViewProfile"),new DesktopStore(root,"development")))using(var tray=new NotifyIcon{Icon=System.Drawing.SystemIcons.Information,Text="ASTRA 043 owned fixture",Visible=true}){
    form.Text="ASTRA 0.4.3 격리 통합 시험";form.EnableDesktopLifecycle();
    form.Shown+=async(s,e)=>{try{
     await form.InitializeAsync(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"WebView2Loader.dll"));var nav=new TaskCompletionSource<bool>();form.Browser.CoreWebView2.NavigationCompleted+=(a,b)=>nav.TrySetResult(b.IsSuccess);form.Browser.Source=new Uri("http://localhost:3000/iris/desktop");Require(await Task.WhenAny(nav.Task,Task.Delay(15000))==nav.Task&&await nav.Task,"navigation");
     if(args[3]=="--connection-probe"){
      await Wait(form,"return !!document.querySelector('form input[autocomplete=username]')||!!document.querySelector('[aria-label=\"생텀 계정 연결됨\"]');","probe session UI");
      if(await Probe(form,"return !!document.querySelector('form input[autocomplete=username]');"))await Login(form,"합성A");
      await Tick(form,true);Stage("probe_ready");
      for(int i=0;i<1200;i++){if(File.Exists(Path.Combine(root,"tick.request"))){File.Delete(Path.Combine(root,"tick.request"));await Tick(form,true);Stage("probe_tick");}if(File.Exists(Path.Combine(root,"close.request"))){await Click(form,"[aria-label='IRIS 종료']");failure=0;await TextClick(form,"종료");return;}await Task.Delay(100);}throw new InvalidOperationException("probe command deadline");
     }
     await Wait(form,"return window.fixtureRelease==='0.4.3'&&document.querySelector('.iris-brand-version')?.textContent==='Beta 0.4.3';","native and web version 0.4.3");
     Stage("full_login_A");await Login(form,"합성A");await Select(form,"합성A");await Tick(form,true);Account("11111111-1111-4111-8111-111111111111");await Capture(form,"workspace-A");
     Stage("floating_sidebar_043");await Click(form,"[aria-label='IRIS 접기']");Invoke(form,"FloatingCommand","menu");await Click(form,"[aria-label='사이드바로 전환']");await Wait(form,"return !!document.querySelector('[aria-label=\"IRIS 접기\"]');","sidebar restored");
     Stage("actual_WebView_HttpOnly_cookie");var cookies=await form.Browser.CoreWebView2.CookieManager.GetCookiesAsync("http://localhost:3000/");bool found=false;foreach(var c in cookies)if(c.Name=="sanctum_session")found=c.IsHttpOnly&&c.Value=="fixture-a";Require(found,"real WebView Set-Cookie");Require(await Probe(form,"return !document.cookie.includes('sanctum_session');"),"HttpOnly invisible");
     Stage("late_A_response_during_B_login");Read("/__fixture/delay-online","POST");var delayed=Tick(form,true);for(int n=0;n<20&&Convert.ToInt32(State()["delayedOnline"])==0;n++)await Task.Delay(25);Require(Convert.ToInt32(State()["delayedOnline"])==1,"native delayed request reached API");
     Stage("account_UI_B");await Click(form,"[aria-label='계정']");await TextClick(form,"다른 계정 로그인");await Login(form,"합성B");await Select(form,"합성B");await delayed;await Tick(form,true);Account("22222222-2222-4222-8222-222222222222");
     Stage("account_UI_A");await Click(form,"[aria-label='계정']");await TextClick(form,"합성A");await Wait(form,"return document.querySelector('.iris-selected-job')?.textContent.includes('합성A');","switch A");await Select(form,"합성A");await Tick(form,true);Account("11111111-1111-4111-8111-111111111111");
     Stage("tray_hide_and_synthetic_suspend");using(var menu=new ContextMenuStrip()){var hide=menu.Items.Add("격리 숨김");hide.Click+=(a,b)=>form.Hide();var show=menu.Items.Add("격리 열기");show.Click+=(a,b)=>form.Show();tray.ContextMenuStrip=menu;hide.PerformClick();Require(tray.Visible&&!form.Visible,"tray hidden");Read("/__fixture/advance","POST");Account(null);show.PerformClick();await Tick(form,true);Account("11111111-1111-4111-8111-111111111111");tray.ContextMenuStrip=null;}
     Stage("network_failure_and_resume");Read("/__fixture/offline","POST");await Tick(form,true);Read("/__fixture/advance","POST");Account(null);Read("/__fixture/offline","DELETE");await Tick(form,true);Account("11111111-1111-4111-8111-111111111111");
     Stage("logout_UI");await Click(form,"[aria-label='계정']");await TextClick(form,"로그아웃");await Wait(form,"return !!document.querySelector('form input[autocomplete=username]');","logout UI");await Tick(form,true);Account(null);await Capture(form,"login-after-logout");
     Stage("relogin_and_normal_close_UI");await Login(form,"합성A");await Tick(form,true);Account("11111111-1111-4111-8111-111111111111");await Click(form,"[aria-label='IRIS 종료']");
     File.WriteAllText(Path.Combine(root,"result.json"),json.Serialize(new{status="PASS",fullDesktopPage=true,nativeAndWebVersion043=true,realAuthUI=true,syntheticAuth=true,realWebViewCookie=true,httpOnly=true,accountABA=true,lateResponseDuringAccountSwitch=true,sidebar043=true,trayMenuPerformClick=true,syntheticSuspend=true,networkFailureResume=true,logout=true,normalCloseUI=true,actualPcSleep=false,actualPostgres=false}));failure=0;await TextClick(form,"종료");
    }catch(Exception error){File.WriteAllText(Path.Combine(root,"failure.txt"),error.ToString());failure=1;form.Dispose();}};
    Application.Run(form);tray.Visible=false;
   }return failure;
  }
 }
}
